<script setup lang="ts">
import { useDialogDraft } from '../dialog-draft'
import { computed, ref } from 'vue'
import type { UserInfo } from '../api'
import { useAdminPage } from '../admin-page'
import { getPlans, savePlan, yuan, type Plan, type PaymentConfig } from '../growth'
const props = defineProps<{ user: UserInfo }>()
const items = ref<Plan[]>([]), config = ref<PaymentConfig | null>(null), selected = ref<Plan | null>(null), dialog = ref(false)
const name = ref(''), description = ref(''), days = ref(30), price = ref(''), active = ref(false), sort = ref(0)
const priceFen = computed(() => { if (!/^\d{1,6}(\.\d{1,2})?$/.test(price.value.trim())) return 0; const [whole = '0', fraction = ''] = price.value.trim().split('.'); return Number(whole) * 100 + Number(fraction.padEnd(2, '0')) })
const page = useAdminPage(async valid => { const result = await getPlans(); if (valid()) { items.value = result.items; config.value = result.configuration } }, () => { dialog.value = false })
const { error, notice, loading, busy } = page
function edit(item: Plan | null = null) { selected.value = item; name.value = item?.name || ''; description.value = item?.description || ''; days.value = item?.days || 30; price.value = item ? (item.price_fen / 100).toFixed(2) : ''; active.value = !!item?.is_active; sort.value = item?.sort_order || 0; error.value = ''; dialog.value = true }
function save() { void page.act(async valid => { await savePlan(props.user.id, { name: name.value.trim(), description: description.value.trim(), days: Number(days.value), price_fen: priceFen.value, is_active: active.value, sort_order: Number(sort.value), revision: selected.value?.revision || 0 }, selected.value?.id); if (valid()) { dialog.value = false; notice.value = '套餐已保存，已有订单仍按下单时的价格与天数结算'; await page.load() } }) }
const draft = useDialogDraft(dialog, () => [name.value, description.value, days.value, price.value, sort.value, active.value], busy, '会员套餐')
</script>
<template><section class="admin-section"><div class="section-toolbar"><p class="text-sm text-muted">套餐名称、价格和会员天数由这里配置，已有订单保留原始价格与权益。</p><div class="actions-row"><UButton label="刷新" variant="outline" :loading="loading" @click="page.load" /><UButton label="新增套餐" icon="i-lucide-plus" @click="edit()" /></div></div><UAlert v-if="config" :title="config.ready ? '在线支付已启用' : config.enabled ? '支付已启用，但配置尚不完整' : '在线支付未启用'" :description="config.ready ? '用户在微信小程序内付款，后台收到微信确认后开通会员。' : '可以先维护套餐。完成商户和回调配置后再启用支付。'" :color="config.ready ? 'success' : 'info'" class="notice" /><UAlert v-if="error" :title="error" color="error" class="notice" /><UAlert v-if="notice" :title="notice" color="success" class="notice" />
  <div class="data-scroll"><table class="data-table"><thead><tr><th>套餐</th><th>会员天数</th><th>价格</th><th>状态</th><th>顺序</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td class="name-cell"><strong>{{ item.name }}</strong><p class="plan-description">{{ item.description }}</p></td><td>{{ item.days }} 天</td><td>{{ yuan(item.price_fen) }}</td><td><UBadge :color="item.is_active ? 'success' : 'neutral'">{{ item.is_active ? '已上架' : '未上架' }}</UBadge></td><td>{{ item.sort_order }}</td><td><UButton label="编辑套餐" variant="soft" @click="edit(item)" /></td></tr><tr v-if="!items.length"><td colspan="6">{{ loading ? '正在加载' : '还没有套餐，请按实际定价新增' }}</td></tr></tbody></table></div>
  <div v-if="config" class="settings-section mt-6"><h3 class="section-title">支付配置检查</h3><p v-if="config.missing.length" class="text-sm text-muted mt-3">待补齐：{{ config.missing.join('、') }}</p><dl class="info-list"><dt>支付回调</dt><dd>{{ config.payment_callback || '未配置' }}</dd><dt>退款回调</dt><dd>{{ config.refund_callback || '未配置' }}</dd><dt>iOS 在线开通</dt><dd>{{ config.ios_enabled ? '已启用' : '未启用' }}</dd></dl><p class="text-sm text-muted mt-4">商户信息、密钥文件和开关通过服务端环境配置；密钥不在后台页面录入或展示。配置项见项目的功能扩展文档。</p></div>
  <UModal v-model:open="draft.model.value" :title="selected ? '编辑会员套餐' : '新增会员套餐'" :dismissible="!busy" :close="!busy"><template #body><form id="membership-plan" class="field-stack" @submit.prevent="save"><UFormField label="套餐名称" required><UInput v-model="name" minlength="2" maxlength="80" required :disabled="busy" class="w-full" /></UFormField><UFormField label="权益说明"><UTextarea v-model="description" maxlength="1000" :disabled="busy" class="w-full" /></UFormField><div class="actions-row"><UFormField label="会员天数" required><UInput v-model="days" type="number" min="1" max="3660" step="1" required :disabled="busy" /></UFormField><UFormField label="价格（元）" required><UInput v-model="price" placeholder="由管理员填写" inputmode="decimal" required :disabled="busy" /></UFormField></div><UFormField label="展示顺序"><UInput v-model="sort" type="number" min="0" max="10000" :disabled="busy" /></UFormField><USwitch v-model="active" label="在小程序上架套餐" :disabled="busy" /><p class="text-sm text-muted">价格支持两位小数。付款成功后从当前有效到期日顺延；已到期用户从开通时开始计算。</p><UAlert v-if="error" :title="error" color="error" /></form></template><template #footer><UButton label="取消" color="neutral" variant="outline" :disabled="busy" @click="draft.setOpen(false)" /><UButton label="保存套餐" type="submit" form="membership-plan" :loading="busy" :disabled="busy || name.trim().length < 2 || priceFen < 1 || priceFen > 10000000" /></template></UModal>
</section></template>
<style scoped>.plan-description { white-space:normal;max-width:380px;margin-top:6px;color:var(--ui-text-muted);font-size:12px;line-height:1.7; }</style>
